const contractStartRaw = $json.contract_start;
const termRaw = $json.contract_term_months;

if (!contractStartRaw) {
  throw new Error('CONTRACT_START_MISSING: contract_start is required to calculate renewal_date.');
}

const term = Number(termRaw);

if (!Number.isInteger(term) || term <= 0) {
  throw new Error('INVALID_CONTRACT_TERM: contract_term_months must be a positive integer.');
}

const start = new Date(contractStartRaw);

if (Number.isNaN(start.getTime())) {
  throw new Error('INVALID_CONTRACT_START: contract_start is not a valid date.');
}

const renewal = new Date(start);
renewal.setMonth(renewal.getMonth() + term);

const renewal_date = renewal.toISOString().slice(0, 10);

return [
  {
    json: {
      ...$json,
      renewal_date
    }
  }
];
